"import dotenv from "dotenv";
import path from "path";
import { fileURLToPath } from "url";
import { streamSimple } from "@earendil-works/pi-ai/dist/api/google-generative-ai.js";
import type { Context, Model } from "@earendil-works/pi-ai";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
dotenv.config({ path: path.resolve(__dirname, "../../.env") });

async function runMinimal() {
  const rawKey = process.env.GEMINI_API_KEY || "";
  const apiKey = rawKey.trim();

  if (!apiKey) {
    throw new Error("GEMINI_API_KEY is not set in .env");
  }

  console.log("Testing Checkpoint 3: Minimal Pi SDK call with ONE model...");

  const model: Model<"google-generative-ai"> = {
    id: "gemini-2.5-flash",
    name: "Gemini 2.5 Flash",
    provider: "google",
    api: "google-generative-ai",
    baseUrl: "https://generativelanguage.googleapis.com",
    reasoning: false,
    input: ["text"],
    cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
    contextWindow: 1048576,
    maxTokens: 8192,
  };

  const context: Context = {
    messages: [
      {
        role: "user",
        content: "Hello",
        timestamp: Date.now(),
      },
    ],
  };

  const stream = streamSimple(model, context, {
    apiKey: apiKey,
  });

  let fullResponse = "";
  for await (const event of stream) {
    if (event.type === "text_delta") {
      process.stdout.write(event.delta);
      fullResponse += event.delta;
    }
  }

  const finalMessage = await stream.result();
  console.log("\n\nFull Response:", fullResponse || JSON.stringify(finalMessage));
  console.log("Checkpoint 3 PASSED: Minimal Pi call succeeded!");
}

runMinimal().catch((err) => {
  console.error("Checkpoint 3 FAILED:", err);
  process.exit(1);
});
"

